INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(7, 'What is the primary objective of applying the Single Responsibility Principle (SRP) in software design?', 'Clean Code & SOLID', 'BEGINNER', 'SOLID, SRP, Clean Architecture', 'To ensure a class executes in a single CPU thread', 'To ensure a class or module has only one reason to change, encapsulating a single responsibility', 'To force every file to have only one function', 'To merge all database queries into one repository', 'B', 'The Single Responsibility Principle (SRP) states that a class should have one, and only one, reason to change, promoting modularity and maintainability.', 'MCQ', TRUE),
(7, 'Which sorting algorithm guarantees O(N log N) time complexity in the worst case and does not require extra memory beyond O(1) auxiliary space?', 'Data Structures & Algorithms', 'INTERMEDIATE', 'HeapSort, Sorting, Time Complexity', 'Merge Sort', 'Quick Sort', 'Heap Sort', 'Bubble Sort', 'C', 'Heap Sort guarantees O(N log N) time complexity in all cases (worst, average, and best) and sorts in-place using O(1) auxiliary space.', 'MCQ', TRUE),
(7, 'What is the time complexity to detect a cycle in a singly linked list using Floyd''s Cycle-Finding Algorithm (Tortoise and Hare)?', 'Data Structures & Algorithms', 'INTERMEDIATE', 'Linked List, Floyd Algorithm, Cycle Detection', 'O(1)', 'O(log N)', 'O(N)', 'O(N^2)', 'C', 'Floyd''s Cycle-Finding algorithm traverses the list using slow and fast pointers, detecting cycles in O(N) time and O(1) extra space.', 'MCQ', TRUE),
(7, 'Which software design pattern is best suited for notifying multiple dependent objects automatically whenever an object changes state?', 'Design Patterns', 'BEGINNER', 'Observer Pattern, GoF Patterns', 'Singleton Pattern', 'Observer Pattern', 'Adapter Pattern', 'Factory Method', 'B', 'The Observer pattern defines a one-to-many dependency between objects so that when one object changes state, all its dependents are notified automatically.', 'MCQ', TRUE),
(7, 'What does the Open/Closed Principle (OCP) in object-oriented design dictate?', 'Clean Code & SOLID', 'BEGINNER', 'SOLID, OCP, Extensibility', 'Classes must be open for modification and closed for extension', 'Software entities should be open for extension, but closed for modification', 'All methods must be public and closed to inheritance', 'Code should only be written once and never touched again', 'B', 'The Open/Closed Principle states that software components should be extendable with new behavior without modifying existing tested source code.', 'MCQ', TRUE),
(7, 'What is the worst-case search time complexity for a key in a standard Binary Search Tree (BST) that has become degenerate/skewed?', 'Data Structures & Algorithms', 'BEGINNER', 'BST, Trees, Search Complexity', 'O(1)', 'O(log N)', 'O(N)', 'O(N log N)', 'C', 'In a degenerate or skewed BST (resembling a linked list), searching degrades to O(N) linear time.', 'MCQ', TRUE),
(7, 'Which design pattern provides an interface for creating families of related or dependent objects without specifying their concrete classes?', 'Design Patterns', 'INTERMEDIATE', 'Abstract Factory, Creational Patterns', 'Builder Pattern', 'Abstract Factory Pattern', 'Prototype Pattern', 'Decorator Pattern', 'B', 'Abstract Factory provides an interface for creating families of related objects without exposing or coupling to their concrete classes.', 'MCQ', TRUE),
(7, 'What is the difference between Unit Testing and Integration Testing in software engineering?', 'Testing & Quality', 'BEGINNER', 'Testing, Unit Tests, Integration Tests', 'Unit tests verify individual functions/classes in isolation; integration tests verify communication across multiple interacting components', 'Unit tests are performed manually by users; integration tests are automated', 'Unit tests test the database; integration tests test the UI', 'There is no difference in modern software engineering', 'A', 'Unit tests isolate and verify individual units of code (often mocking dependencies), while integration tests verify components working together.', 'MCQ', TRUE),
(7, 'What is the primary difference between a process and a thread in modern operating systems?', 'Operating Systems', 'BEGINNER', 'Processes, Threads, OS Internals', 'Processes share memory address space; threads have independent address spaces', 'A process has its own dedicated virtual address space; threads within the same process share that memory space', 'Threads cannot run concurrently on multiple CPU cores', 'Processes execute 100x faster than threads', 'B', 'Processes are independent execution units with private virtual address spaces, while threads within a process share code, data, and open file handles.', 'MCQ', TRUE),
(7, 'In Git version control, what does git rebase accomplish compared to git merge?', 'Version Control', 'INTERMEDIATE', 'Git, Rebase, Merge, Branching', 'git rebase deletes old commits permanently without trace', 'git rebase replays your branch commits on top of another base branch, creating a clean linear commit history; merge creates a merge commit', 'git rebase is only used to push commits to production', 'git merge modifies author timestamps while rebase does not', 'B', 'git rebase moves the base of your branch to the tip of another, producing a linear commit history without extraneous merge commits.', 'MCQ', TRUE),
(7, 'What is the Liskov Substitution Principle (LSP) in object-oriented architecture?', 'Clean Code & SOLID', 'INTERMEDIATE', 'SOLID, LSP, Polymorphism', 'Subtypes must be substitutable for their base types without altering the correctness of the program', 'Base classes must inherit from derived classes', 'Subclasses must override every method of the superclass', 'Interfaces cannot have more than two methods', 'A', 'LSP requires that objects of a superclass should be replaceable with objects of its subclasses without breaking application behavior.', 'MCQ', TRUE),
(7, 'Which data structure is typically used to implement Breadth-First Search (BFS) in a graph or tree?', 'Data Structures & Algorithms', 'BEGINNER', 'BFS, Queue, Graph Traversal', 'Stack', 'Queue', 'Priority Queue', 'Hash Table', 'B', 'BFS traverses level by level and uses a FIFO (First-In-First-Out) Queue to explore neighbor nodes in order of discovery.', 'MCQ', TRUE),
(7, 'What does continuous integration (CI) mean in modern software engineering pipelines?', 'DevOps & CI/CD', 'BEGINNER', 'CI/CD, Automation, DevOps', 'Deploying code directly to production without running tests', 'Regularly merging code changes into a central repository followed by automated builds and test executions', 'Writing code continuously without code reviews', 'Rebuilding the entire database nightly', 'B', 'Continuous Integration is the practice of automating the integration, building, and automated testing of code changes from multiple contributors.', 'MCQ', TRUE),
(7, 'What is a memory leak in a managed runtime environment like Java or Node.js?', 'Debugging & Runtime', 'INTERMEDIATE', 'Memory Leak, Garbage Collection', 'Physical destruction of RAM hardware', 'Unused objects remain reachable by lingering references, preventing the garbage collector from reclaiming their allocated memory', 'Immediate program termination due to zero free disk space', 'Memory allocated to the operating system kernel', 'B', 'Even in garbage-collected environments, holding onto object references (e.g. in static collections or unremoved listeners) prevents GC deallocation.', 'MCQ', TRUE),
(7, 'Which algorithmic paradigm does Dijkstra''s Algorithm use to compute the shortest paths in a graph with non-negative edge weights?', 'Data Structures & Algorithms', 'INTERMEDIATE', 'Dijkstra, Greedy, Shortest Path', 'Divide and Conquer', 'Greedy Algorithm', 'Dynamic Programming', 'Backtracking', 'B', 'Dijkstra''s algorithm is a greedy algorithm that iteratively selects the unvisited node with the smallest tentative distance.', 'MCQ', TRUE),
(7, 'What is the Decorator design pattern used for in software architecture?', 'Design Patterns', 'INTERMEDIATE', 'Decorator Pattern, Structural Patterns', 'Connecting to relational databases', 'Attaching additional responsibilities or behaviors to an object dynamically without altering its structure or using subclassing', 'Compressing JSON responses', 'Creating single shared instances', 'B', 'The Decorator pattern wraps an object to dynamically add behavior at runtime without extending the base class through rigid inheritance.', 'MCQ', TRUE),
(7, 'What is a race condition in concurrent software systems?', 'Concurrency', 'INTERMEDIATE', 'Race Condition, Concurrency, Synchronization', 'A competition between servers for the fastest network ping', 'A situation where system behavior depends on the uncontrollable timing or interleaving of multiple concurrent threads', 'A loop that never terminates', 'An algorithm with O(N!) complexity', 'B', 'A race condition occurs when multiple threads concurrently read and write shared data without synchronization, producing non-deterministic outcomes.', 'MCQ', TRUE),
(7, 'What is the time complexity of building a heap (heapify) from an unordered array of N elements?', 'Data Structures & Algorithms', 'ADVANCED', 'Heapify, Binary Heap, Time Complexity', 'O(1)', 'O(N)', 'O(N log N)', 'O(N^2)', 'B', 'Building a heap bottom-up from an array takes O(N) linear time, not O(N log N), because nodes near the bottom require fewer swap steps.', 'MCQ', TRUE),
(7, 'In API development, what is semantic versioning (SemVer) format (MAJOR.MINOR.PATCH)?', 'Software Architecture', 'BEGINNER', 'SemVer, Versioning, API Contracts', 'MAJOR for backwards-incompatible changes, MINOR for backwards-compatible features, PATCH for backwards-compatible bug fixes', 'MAJOR for date, MINOR for time, PATCH for author ID', 'MAJOR for lines of code, MINOR for functions, PATCH for bugs', 'It is an arbitrary sequence of numbers decided by developers', 'A', 'SemVer specifies: MAJOR version when you introduce breaking API changes, MINOR for backwards-compatible additions, and PATCH for bug fixes.', 'MCQ', TRUE),
(7, 'What is the purpose of Mocking dependencies during unit testing?', 'Testing & Quality', 'BEGINNER', 'Unit Testing, Mocking, Mockito', 'To test live third-party network APIs in production', 'To simulate behavior of complex, slow, or external dependencies (like databases or web services) to test units in isolation', 'To speed up code execution in production runtime', 'To generate fake test data for customers', 'B', 'Mocking isolates the unit under test from real external systems, ensuring unit tests execute deterministically and fast without real side effects.', 'MCQ', TRUE),
(7, 'What is the primary difference between a stack and a heap in computer memory architecture?', 'Computer Architecture', 'INTERMEDIATE', 'Stack vs Heap, Memory Management', 'Stack stores large dynamic objects; heap stores local primitive variables', 'Stack handles fast, automatic LIFO allocation for function call frames; heap handles dynamic memory allocations managed at runtime', 'Stack memory is persistent across reboots; heap memory is volatile', 'Stack memory is unlimited; heap memory is fixed at 1MB', 'B', 'The Stack provides fast, deterministic LIFO allocation for method execution frames; the Heap provides dynamic memory for objects with flexible lifecycles.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(8, 'In statistical analysis, what is the key difference between Mean and Median when analyzing skewed income data?', 'Statistics', 'BEGINNER', 'Statistics, Mean vs Median, Skewness', 'Mean is unaffected by extreme outliers; median is heavily distorted', 'Median is resistant to extreme outliers and represents the 50th percentile; mean is pulled toward the skew direction', 'They are mathematically identical for all distributions', 'Median is only valid for categorical string data', 'B', 'In skewed distributions (like salary or housing prices), the mean is pulled by extreme values, whereas the median robustly represents the central tendency.', 'MCQ', TRUE),
(8, 'Which SQL clause is used to calculate aggregations over a subset of rows without collapsing the underlying result rows?', 'SQL Analytics', 'INTERMEDIATE', 'Window Functions, OVER, PARTITION BY', 'GROUP BY', 'HAVING', 'OVER (PARTITION BY ...)', 'WHERE IN', 'C', 'SQL window functions using the OVER (PARTITION BY ...) clause compute aggregations across partitions while maintaining individual row granularity.', 'MCQ', TRUE),
(8, 'In Python Pandas, what is the difference between df.loc[] and df.iloc[]?', 'Python & Pandas', 'BEGINNER', 'Pandas, DataFrame, Indexing', 'df.loc uses label-based indexing; df.iloc uses integer position-based indexing', 'df.loc is used only for columns; df.iloc is used only for rows', 'df.iloc is 100x slower than df.loc', 'They are completely identical functions', 'A', 'loc[] selects rows and columns by labels/names, while iloc[] selects strictly by zero-based integer positional coordinates.', 'MCQ', TRUE),
(8, 'What is the purpose of an exploratory data analysis (EDA) phase in an analytics project?', 'Data Analytics Methodology', 'BEGINNER', 'EDA, Data Exploration, Data Quality', 'To deploy predictive machine learning models immediately', 'To understand data distributions, detect anomalies/outliers, verify hypotheses, and assess data quality before modeling', 'To encrypt database tables for GDPR compliance', 'To convert numeric columns into binary values', 'B', 'EDA explores the main characteristics of data through summary statistics and visual representations to uncover patterns and anomalies.', 'MCQ', TRUE),
(8, 'In A/B testing, what does the p-value represent when testing a null hypothesis?', 'Hypothesis Testing', 'INTERMEDIATE', 'p-value, Hypothesis Testing, A/B Testing', 'The probability that the alternative hypothesis is true', 'The probability of observing results at least as extreme as the current data assuming the null hypothesis is true', 'The percentage improvement of version B over version A', 'The statistical power of the test', 'B', 'The p-value measures the evidence against the null hypothesis: a small p-value (typically <= 0.05) indicates that observed data is unlikely under H0.', 'MCQ', TRUE),
(8, 'What type of chart is most appropriate for visualizing the correlation relationship between two continuous numerical variables?', 'Data Visualization', 'BEGINNER', 'Data Visualization, Scatter Plot, Correlation', 'Pie Chart', 'Bar Chart', 'Scatter Plot', 'Stacked Area Chart', 'C', 'A scatter plot places one continuous variable on the X-axis and the other on the Y-axis, directly revealing linear or non-linear correlation patterns.', 'MCQ', TRUE),
(8, 'What is the difference between a Type I error and a Type II error in statistical hypothesis testing?', 'Statistics', 'INTERMEDIATE', 'Type I vs Type II Error, Statistics', 'Type I error is a False Positive (rejecting true H0); Type II error is a False Negative (failing to reject false H0)', 'Type I error is a False Negative; Type II is a False Positive', 'Type I errors only happen in small datasets', 'Type II errors mean the data contains missing values', 'A', 'A Type I error occurs when you reject a true null hypothesis (false alarm); a Type II error occurs when you fail to reject a false null hypothesis.', 'MCQ', TRUE),
(8, 'In data warehousing, what is the defining characteristic of a Star Schema?', 'Data Modeling', 'INTERMEDIATE', 'Data Warehousing, Star Schema, Fact Table', 'A central Fact table containing numeric measurements surrounded by denormalized Dimension tables', 'A fully normalized database in Third Normal Form', 'A database with no primary or foreign keys', 'A schema containing only views and stored procedures', 'A', 'A star schema features a central fact table holding foreign keys and additive metrics, directly connected to surrounding dimensional lookup tables.', 'MCQ', TRUE),
(8, 'In Python Pandas, which method is best suited for handling missing (NaN) values by replacing them with the column mean?', 'Python & Pandas', 'BEGINNER', 'Pandas, Imputation, fillna', 'df.dropna()', 'df.fillna(df.mean())', 'df.replace()', 'df.interpolate_nulls()', 'B', 'df.fillna(df.mean()) performs mean imputation across numeric columns, replacing missing values with their respective arithmetic means.', 'MCQ', TRUE),
(8, 'What is the purpose of calculating Customer Lifetime Value (CLV or LTV) in business intelligence?', 'Business Analytics', 'INTERMEDIATE', 'CLV, Metrics, Business Analytics', 'To track employee working hours', 'To estimate the total revenue a business can reasonably expect from a single customer account throughout their relationship', 'To calculate server hosting costs', 'To measure website latency', 'B', 'Customer Lifetime Value predicts the net monetary value of the ongoing relationship with a customer, informing acquisition and retention strategies.', 'MCQ', TRUE),
(8, 'What does the Pearson correlation coefficient (r = -0.85) between two variables indicate?', 'Statistics', 'BEGINNER', 'Correlation, Pearson, Statistics', 'No linear relationship between variables', 'A strong negative linear relationship: as one variable increases, the other systematically decreases', 'A weak positive relationship', 'That one variable causes the other directly', 'B', 'Pearson r ranges from -1 to +1; a value of -0.85 demonstrates a strong inverse linear relationship, though correlation does not imply causation.', 'MCQ', TRUE),
(8, 'In SQL, what is the difference between COUNT(*) and COUNT(column_name)?', 'SQL Analytics', 'BEGINNER', 'SQL, Aggregate Functions, COUNT', 'COUNT(*) counts all rows including NULLs; COUNT(column_name) counts only rows where column_name is NOT NULL', 'COUNT(column_name) counts all rows including NULLs; COUNT(*) does not', 'They always return the exact same count', 'COUNT(*) only works on indexed columns', 'A', 'COUNT(*) counts every row in the result set regardless of NULL values, whereas COUNT(col) ignores rows where that specific column contains NULL.', 'MCQ', TRUE),
(8, 'What is the primary purpose of data normalization (min-max scaling or z-score standardization) before statistical modeling?', 'Data Preprocessing', 'INTERMEDIATE', 'Scaling, Normalization, Standardization', 'To eliminate duplicate records from the dataset', 'To bring numerical features to a comparable scale so variables with large ranges do not artificially dominate distance-based computations', 'To convert text columns to integers', 'To reduce the total number of rows', 'B', 'Feature scaling ensures all numerical inputs contribute proportionately, preventing large magnitude features from biasing algorithms.', 'MCQ', TRUE),
(8, 'In business reporting, what does the churn rate metric measure?', 'Business Analytics', 'BEGINNER', 'Churn Rate, Retention, Metrics', 'The rate at which new customers are acquired', 'The percentage of customers or subscribers who stop doing business or cancel their subscriptions over a given timeframe', 'The total number of page views on a website', 'The average order value of products sold', 'B', 'Churn rate quantifies the percentage of customers who discontinue their relationship with a service over a designated observation period.', 'MCQ', TRUE),
(8, 'Which visual element in a Box-and-Whisker plot (Boxplot) indicates the Interquartile Range (IQR)?', 'Data Visualization', 'BEGINNER', 'Boxplot, IQR, Statistics', 'The distance between the two extreme whisker ends', 'The height/length of the central box spanning the 25th percentile (Q1) to the 75th percentile (Q3)', 'The solitary dots plotted beyond the whiskers', 'The median line dividing the box', 'B', 'The box encompasses the middle 50% of the distribution between Q1 and Q3, with its span directly representing the Interquartile Range (IQR).', 'MCQ', TRUE),
(8, 'In Pandas, what operation does the df.pivot_table() function perform?', 'Python & Pandas', 'INTERMEDIATE', 'Pandas, Pivot Table, Reshaping', 'Transposes rows and columns without aggregation', 'Aggregates and reshapes DataFrame data into a multidimensional summary table using specified index, columns, and aggregate functions', 'Deletes all empty columns', 'Exports data to an Excel spreadsheet', 'B', 'pivot_table spreadsheet-style aggregates data, grouping by index and column coordinates while applying aggregate functions (like mean or sum).', 'MCQ', TRUE),
(8, 'What is the difference between a dimensional model Fact table and a Dimension table?', 'Data Warehousing', 'INTERMEDIATE', 'Data Modeling, Fact vs Dimension', 'Fact tables contain qualitative attributes; Dimension tables contain numeric IDs', 'Fact tables contain quantitative metrics/measurements and foreign keys; Dimension tables contain descriptive contextual attributes', 'Dimension tables change every millisecond; Fact tables never change', 'There is no difference in Kimball methodology', 'B', 'Fact tables store numerical business events and measurements (e.g. sales amounts); dimension tables provide context (who, what, where, when).', 'MCQ', TRUE),
(8, 'In SQL, what is the result of applying the DENSE_RANK() window function when two rows tie for second place?', 'SQL Analytics', 'INTERMEDIATE', 'DENSE_RANK, Window Functions, Ties', '1, 2, 2, 4 (skips 3)', '1, 2, 2, 3 (no rank numbers are skipped)', '1, 2, 3, 4 (breaks ties arbitrarily)', 'An error is thrown', 'B', 'DENSE_RANK() does not skip rank values after ties: tied records receive rank 2, and the immediately following row receives rank 3.', 'MCQ', TRUE),
(8, 'What is Simpson''s Paradox in data analysis?', 'Statistical Paradoxes', 'ADVANCED', 'Simpson Paradox, Confounding Variables', 'When statistical significance increases as sample size decreases', 'A trend that appears across several different groups disappears or reverses when the groups are combined', 'When correlation equals causation in large datasets', 'When the mean and median of a dataset are identical', 'B', 'Simpson''s Paradox occurs when aggregate data contradicts subgroup trends, typically caused by an unobserved confounding variable.', 'MCQ', TRUE),
(8, 'What is the difference between inner merge and outer merge in Python Pandas (pd.merge)?', 'Python & Pandas', 'BEGINNER', 'Pandas, Merge, Joins', 'Inner merge keeps only common keys found in both DataFrames; outer merge retains all records from both, filling unmatched values with NaN', 'Outer merge deletes all records that have matching keys', 'Inner merge can only merge two single-column DataFrames', 'They produce the exact same DataFrame output', 'A', 'An inner merge retains rows with matching keys in both DataFrames; an outer merge takes the union, preserving all rows and padding with NaN.', 'MCQ', TRUE),
(8, 'What does the standard deviation of a dataset measure?', 'Statistics', 'BEGINNER', 'Standard Deviation, Dispersion, Statistics', 'The central middle value of the distribution', 'The amount of variation, dispersion, or spread of values around the arithmetic mean', 'The total number of data points', 'The difference between the maximum and minimum values', 'B', 'Standard deviation quantifies the dispersion of values around the mean: low SD indicates values clustered tightly; high SD indicates wide dispersion.', 'MCQ', TRUE);
INSERT INTO questions (job_role_id, question_text, category, difficulty, expected_topics, option_a, option_b, option_c, option_d, correct_option, explanation, question_type, active) VALUES
(9, 'What does the Bias-Variance Tradeoff represent in supervised machine learning?', 'Machine Learning Core', 'INTERMEDIATE', 'Bias-Variance, Overfitting, Underfitting', 'High bias leads to overfitting; high variance leads to underfitting', 'High bias causes underfitting (oversimplified model); high variance causes overfitting (sensitive to training noise)', 'Bias and variance can both be reduced to zero simultaneously in any model', 'It measures the speed of model gradient descent convergence', 'B', 'Bias reflects error from erroneous assumptions (underfitting); variance reflects sensitivity to small training data fluctuations (overfitting).', 'MCQ', TRUE),
(9, 'Why is Precision preferred over Accuracy when evaluating machine learning models on highly imbalanced datasets (e.g., fraud detection where 0.1% are positive)?', 'Model Evaluation', 'BEGINNER', 'Evaluation Metrics, Precision, Imbalanced Data', 'Accuracy can be misleadingly high (e.g. 99.9%) by simply predicting all samples as negative, whereas Precision measures exactness of positive predictions', 'Precision is faster to compute than Accuracy', 'Accuracy cannot be calculated for binary classification', 'Precision measures total training loss', 'A', 'On heavily skewed data, a naive model predicting the majority class scores high accuracy while completely failing to detect positive fraud instances.', 'MCQ', TRUE),
(9, 'What is the vanishing gradient problem in deep neural networks and which activation function helps mitigate it?', 'Deep Learning', 'INTERMEDIATE', 'Vanishing Gradient, ReLU, Activations', 'Gradients grow exponentially; solved using Sigmoid activation', 'Gradients become vanishingly small as backpropagation flows through many layers; mitigated using ReLU (Rectified Linear Unit)', 'Loss becomes negative; mitigated by Tanh', 'Weights oscillate indefinitely; mitigated by Step function', 'B', 'Sigmoid and Tanh saturate at extreme values with near-zero derivatives; ReLU has a constant derivative of 1 for positive inputs, preventing gradient decay.', 'MCQ', TRUE),
(9, 'What is the difference between L1 regularization (Lasso) and L2 regularization (Ridge) in loss function penalties?', 'Regularization', 'INTERMEDIATE', 'Regularization, L1, L2, Lasso, Ridge', 'L1 penalizes squared weights; L2 penalizes absolute weights', 'L1 penalizes the sum of absolute weights and promotes feature sparsity (driving weights to zero); L2 penalizes squared weights (shrinking weights smoothly)', 'L1 regularization cannot be used with linear regression', 'L2 regularization eliminates features completely', 'B', 'L1 (Lasso) drives uninformative feature coefficients exactly to zero, performing implicit feature selection; L2 (Ridge) shrinks weights toward zero without setting them to zero.', 'MCQ', TRUE),
(9, 'What is the Self-Attention mechanism in the Transformer architecture?', 'Transformers & NLP', 'ADVANCED', 'Self-Attention, Transformers, Scaled Dot-Product', 'A method to train models using only labeled output data', 'A mechanism computing attention weights between all pairs of tokens in an input sequence simultaneously, capturing long-range contextual relationships', 'A recurrent loop that passes hidden state sequentially from left to right', 'A convolutional filter applied to sentences', 'B', 'Self-attention maps Query, Key, and Value representations, computing dynamic weights that allow each token to attend to all other tokens in the sequence.', 'MCQ', TRUE),
(9, 'What is the primary purpose of the Dropout technique during deep neural network training?', 'Deep Learning', 'BEGINNER', 'Dropout, Regularization, Overfitting', 'To discard low-quality training images permanently', 'To randomly deactivate a fraction of neurons during training passes, preventing co-adaptation of features and reducing overfitting', 'To accelerate model inference speed in production', 'To reduce the number of training epochs required', 'B', 'Dropout acts as ensemble regularization by randomly disabling units and their connections during training, forcing redundant feature representations.', 'MCQ', TRUE),
(9, 'In training large neural networks, what problem does Adam optimizer address compared to standard Stochastic Gradient Descent (SGD)?', 'Optimization', 'INTERMEDIATE', 'Optimization, Adam, SGD, Learning Rate', 'It eliminates the need for backpropagation', 'It computes adaptive learning rates for each parameter using running estimates of both first (mean) and second (uncentered variance) moments of gradients', 'It converts non-convex loss surfaces into strictly convex surfaces', 'It guarantees 100% test accuracy', 'B', 'Adam (Adaptive Moment Estimation) combines the advantages of AdaGrad and RMSProp, maintaining per-parameter adaptive learning rates based on moments.', 'MCQ', TRUE),
(9, 'What does the ROC-AUC score measure in binary classification?', 'Model Evaluation', 'INTERMEDIATE', 'ROC-AUC, Model Evaluation, Classification', 'The overall training time of the classifier', 'The ability of the model to distinguish between positive and negative classes across all classification probability thresholds', 'The percentage of true negative predictions only', 'The linear correlation of feature inputs', 'B', 'The Area Under the Receiver Operating Characteristic curve (ROC-AUC) plots TPR vs FPR across all thresholds, measuring discriminative power independent of threshold.', 'MCQ', TRUE),
(9, 'What is Transfer Learning and how is it commonly applied in modern Computer Vision or NLP?', 'Deep Learning', 'BEGINNER', 'Transfer Learning, Pretrained Models, Fine-tuning', 'Transferring model weights to a different programming language', 'Taking a model pre-trained on a massive dataset (e.g. ImageNet or language corpus) and fine-tuning its weights on a smaller domain-specific task', 'Training two identical models simultaneously on the same data', 'Exporting models to ONNX format', 'B', 'Transfer learning leverages general feature representations learned by foundation models, drastically reducing training data and compute requirements.', 'MCQ', TRUE),
(9, 'What is the role of the loss function in training machine learning models?', 'Machine Learning Core', 'BEGINNER', 'Loss Function, Optimization, Objective', 'To validate data types in the input DataFrame', 'To quantify the error or discrepancy between model predictions and actual target values, providing an objective metric for optimization', 'To encrypt model weights during storage', 'To schedule automated backups of training checkpoints', 'B', 'The loss function quantifies how well the algorithm models the given data; minimizing this loss via optimization algorithms trains the model.', 'MCQ', TRUE),
(9, 'In Natural Language Processing, what are vector embeddings (e.g. Word2Vec, BERT embeddings)?', 'NLP', 'INTERMEDIATE', 'Embeddings, Vector Space, NLP', 'A list of words sorted alphabetically', 'Dense, continuous numerical vector representations of tokens where semantically similar words are positioned close together in vector space', 'Binary flags indicating part of speech', 'Encrypted strings representing sentences', 'B', 'Embeddings map discrete words or text chunks to continuous high-dimensional vector spaces, capturing semantic and relational similarities.', 'MCQ', TRUE),
(9, 'What is the purpose of Cross-Validation (e.g., K-Fold Cross-Validation) in model training?', 'Model Validation', 'BEGINNER', 'Cross-Validation, K-Fold, Generalization', 'To increase the size of the test dataset by duplicating rows', 'To assess how the model generalizes to independent data by partitioning the dataset into K subsets and training/testing K times', 'To eliminate the need for training epochs', 'To speed up training by running across K GPUs', 'B', 'K-Fold Cross-Validation provides a robust estimate of model performance and prevents overfitting to a single arbitrary train/test split.', 'MCQ', TRUE),
(9, 'In unsupervised machine learning, how does the K-Means clustering algorithm assign data points to clusters?', 'Clustering', 'INTERMEDIATE', 'K-Means, Clustering, Centroids', 'By building a hierarchical tree of nodes', 'By initializing K centroids, assigning each point to the nearest centroid, and iteratively updating centroids to the mean of assigned points until convergence', 'By calculating density around core points', 'By training a deep neural network with cross-entropy loss', 'B', 'K-Means alternates between assigning observations to the nearest cluster centroid (by Euclidean distance) and recalculating centroids as the cluster mean.', 'MCQ', TRUE),
(9, 'What does the F1-Score represent in classification model evaluation?', 'Model Evaluation', 'BEGINNER', 'F1-Score, Precision, Recall', 'The arithmetic mean of accuracy and loss', 'The harmonic mean of Precision and Recall, providing a balanced metric especially when classes are unevenly distributed', 'The maximum prediction speed of the model', 'The probability of false positive classification', 'B', 'The F1-score balances precision and recall using their harmonic mean: F1 = 2 * (Precision * Recall) / (Precision + Recall).', 'MCQ', TRUE),
(9, 'What is the purpose of Batch Normalization in deep convolutional or feedforward networks?', 'Deep Learning', 'INTERMEDIATE', 'Batch Normalization, Deep Learning, Covariate Shift', 'To normalize images to grayscale before training', 'To normalize layer activations across each mini-batch, stabilizing gradient flow and enabling higher learning rates with faster convergence', 'To reduce the dataset size by averaging batches', 'To delete outlier samples from the training set', 'B', 'Batch Normalization standardizes inputs to intermediate layers, mitigating internal covariate shift and acting as a mild regularizer.', 'MCQ', TRUE),
(9, 'What is a Retrieval-Augmented Generation (RAG) architecture in modern generative AI?', 'Generative AI & LLMs', 'ADVANCED', 'RAG, LLM, Vector Search, Semantic Retrieval', 'Generating synthetic training data using GANs', 'Combining a semantic retrieval system (searching external vector databases for relevant context) with a generative LLM to provide grounded, factual responses', 'Compressing neural network weights to 4-bit quantization', 'Training an LLM from scratch on internal PDFs', 'B', 'RAG retrieves relevant external knowledge chunks from a vector database and injects them into the LLM prompt context to ground responses.', 'MCQ', TRUE),
(9, 'In decision trees, what does Gini Impurity measure?', 'Decision Trees', 'INTERMEDIATE', 'Gini Impurity, Decision Trees, Information Gain', 'The time taken to split a tree node', 'The probability of incorrectly classifying a randomly chosen element from the set if it were randomly labeled according to the class distribution in the node', 'The tree depth limit', 'The number of continuous features in the dataset', 'B', 'Gini impurity measures node purity: a pure node has Gini = 0; splitting algorithms choose splits that maximize Gini impurity reduction.', 'MCQ', TRUE),
(9, 'What is gradient clipping used for when training deep recurrent networks (RNNs/LSTMs)?', 'Deep Learning', 'INTERMEDIATE', 'Gradient Clipping, Exploding Gradients, RNN', 'To discard irrelevant input sequences', 'To prevent exploding gradients by scaling down the gradient vector when its norm exceeds a specified threshold', 'To prevent vanishing gradients', 'To automatically stop training after 10 epochs', 'B', 'Gradient clipping caps the maximum magnitude of gradient updates, preventing numerical instability and exploding gradients during backpropagation through time.', 'MCQ', TRUE),
(9, 'What is the difference between supervised, unsupervised, and reinforcement learning?', 'Machine Learning Core', 'BEGINNER', 'Learning Paradigms, Supervised, Unsupervised, RL', 'Supervised learns from labeled input-output pairs; unsupervised discovers hidden patterns in unlabeled data; reinforcement learns optimal policies through reward feedback', 'Supervised is for text; unsupervised is for images; reinforcement is for audio', 'Supervised requires no data; unsupervised requires labeled data', 'They are synonymous terms for deep learning', 'A', 'Supervised learning maps features to labeled targets; unsupervised finds patterns without labels; reinforcement learning optimizes actions via environmental rewards.', 'MCQ', TRUE),
(9, 'What is model quantization in deep learning deployment (e.g. FP32 to INT8)?', 'Model Deployment', 'ADVANCED', 'Quantization, Model Optimization, Inference', 'Training a neural network using quantum computers', 'Converting model weights and activations from high-precision floating point (e.g. 32-bit) to lower-bit representations (e.g. 8-bit integer) to reduce memory and accelerate inference', 'Pruning 90% of model layers permanently', 'Encrypting model tensors with RSA keys', 'B', 'Quantization approximates floating-point values with reduced bit-width integers, shrinking model memory footprints and accelerating inference latency.', 'MCQ', TRUE),
(9, 'What is data leakage (target leakage) in machine learning modeling?', 'Machine Learning Methodology', 'INTERMEDIATE', 'Data Leakage, Target Leakage, Overfitting', 'A cyber security breach exposing private training data', 'Information from outside the training dataset (or future information not available at inference time) contaminating the model during training, creating overly optimistic metrics', 'Loss of training images during data augmentation', 'When model weights are leaked to competitors', 'B', 'Data leakage occurs when target information leaks into training features (e.g. scaling before train-test split), leading to failure in real-world production.', 'MCQ', TRUE);
